"""User-selected hosted game and a quiet, single-column play page."""
GAME = 'https://pokemon-team-builder.org/pokebonk/play/?lang=en'
HOST = 'https://pokemon-team-builder.org/pokebonk'


def add_play(ctx):
    p, pages = ctx['P'], ctx['PAGES']
    ext, ref = ctx['ext'], ctx['ref']
    title = 'Play PokeBonk Online — Game Window & Guides'
    desc = 'Play a hosted PokeBonk version in your browser, expand or minimize the game, and read first-run tips below. Accounts and progress belong to its host.'
    body = f'''<nav class="crumbs" aria-label="Breadcrumb" data-play-background><a href="{p}">PokeBonk</a> / Play</nav>
<header class="play-intro" id="guide" data-play-background><p class="play-kicker">PokéBonk v0.8.27 · Browser game · Third-party host</p><h1>Play PokeBonk Online</h1><p>Jump into a run, then keep the guide below within reach.</p></header>
<section class="game-panel" id="game-panel" aria-label="PokeBonk game window" data-mode="normal">
<div class="game-screen" id="game-screen"><div class="game-cover" id="game-cover"><div><span class="play-emblem" aria-hidden="true">✦</span><h2>PokéBonk</h2><p>A 3D Pokémon survivor, right in your browser.</p><button class="play-button" type="button" id="game-launch">Play PokeBonk <span aria-hidden="true">→</span></button><p class="cover-note">Loads the game from pokemon-team-builder.org</p><noscript><p>Enable JavaScript or use the game-host link below.</p></noscript></div></div>
<iframe id="game-frame" title="PokeBonk game hosted by Pokemon Team Builder" data-src="{GAME}" allow="autoplay; fullscreen; gamepad" allowfullscreen sandbox="allow-scripts allow-same-origin allow-forms allow-pointer-lock allow-orientation-lock" referrerpolicy="strict-origin-when-cross-origin" hidden></iframe></div>
<div class="game-meta"><p>Game hosted by {ext(HOST, 'Pokemon Team Builder')}. Accounts and progress are separate from pokebonk.com.{ref(1)}</p><div class="game-tools"><button type="button" id="game-expand" aria-pressed="false" disabled>Expand</button><button type="button" id="game-minimize" aria-expanded="true" aria-controls="game-screen" disabled>Minimize</button>{ext(GAME, 'Open game in a new tab')}</div><p id="game-status" role="status" aria-live="polite">Click Play to load the game. On phones, rotate to landscape.</p></div></section>
<div class="game-dock" id="game-dock" hidden><span>PokéBonk minimized</span><button type="button" id="game-restore">Restore game</button></div>
<article class="play-notes prose" data-play-background><p class="play-summary">Choose a partner, survive the hordes and build your League. Pause inside the game before reading: minimizing this window does not pause a run.</p><nav class="play-jump" aria-label="Play guide sections"><a href="#first-run">First run</a><a href="#controls">Controls</a><a href="#starter">Starters</a><a href="#saves">Saves &amp; help</a></nav>
<section id="first-run"><h2>How to start your first run</h2><ol><li>Press <strong>Play PokeBonk</strong>, then choose <strong>Play as a guest!</strong> in the game.</li><li>Select a starter and confirm the button naming that partner.</li><li>From the main menu, choose <strong>Play</strong>. In the League, confirm the Pokémon with <strong>I choose you!</strong></li><li>Choose <strong>Viridian Forest</strong> and <strong>Normal</strong>, then press <strong>Start!</strong></li><li>Keep moving and gather experience. When an upgrade appears, read whether it changes an owned move, adds a new attack or improves a stat.</li></ol><p>We checked this Guest-to-run route in the host’s v0.8.27 on October 26, 2026, and reached Viridian Forest, Zone 1/3. This was a startup check, not a completed run or a performance benchmark.{ref(1)}</p><p>For more detail, see the <a href="{p}beginners-guide/">beginner guide</a>. Its newer-build menus can differ from this hosted version.</p></section>
<section id="controls"><h2>Keep the game and your guide handy</h2><p>Click inside the game to give it keyboard focus. Use its Settings → Controls screen to check or change the keys for this version.</p><ul><li><strong>Expand</strong> gives the game more browser space. Exit expanded view returns to the page.</li><li><strong>Minimize</strong> folds the game away while you read. The Restore game button stays at the bottom of the screen.</li><li><strong>Restore</strong> keeps the same frame loaded; it does not deliberately refresh the game.</li><li><strong>Pause inside the game first.</strong> Our window controls cannot pause a cross-origin game for you.</li></ul></section>
<section id="starter"><h2>Choose a starter by what you want to learn</h2><p>The checked entry screen offers Bulbasaur, Charmander and Squirtle. Read the selected partner’s actual passive before confirming.</p><ul><li><strong>Bulbasaur:</strong> its Healer role is a starting point for learning recovery.</li><li><strong>Charmander:</strong> its Fire-focused role is a starting point for learning offensive choices.</li><li><strong>Squirtle:</strong> its Defender role is a starting point for learning defensive positioning.</li></ul><p>These are role-based directions, not a measured strongest-starter ranking. Our <a href="{p}starters/">starter comparison</a>, <a href="{p}evolution/">evolution guide</a> and <a href="{p}builds/">build planner guide</a> cover newer checked beta builds; use this game’s displayed values if they differ.{ref(1)}</p></section>
<section id="saves"><h2>Your save belongs to the game host</h2><p>This window loads a version hosted by Pokemon Team Builder. The host states that its accounts and progress are separate from pokebonk.com. We do not operate its servers or manage your game account.{ref(1)}</p><p>The startup check covered Guest entry, a starter choice and entering a Classic run. We have not verified named-account sign-in, save recovery, multiplayer or long-term host availability. For existing progress, check which game host created your account before signing in.</p><p>If the host stops loading, use {ext(GAME, 'the hosted game in its own tab')} or {ext('https://pokebonk.com/?lang=en', 'the original PokeBonk project')}. The original project is a separate service and may be on a different version.{ref(2)}</p><p>See our <a href="{p}privacy/#game-window">game-window privacy notice</a> for third-party loading and storage.</p></section>
{ctx['source_list']([(HOST, 'Pokemon Team Builder hosted version', 'October 26, 2026: displayed v0.8.27; Guest entry and Classic startup checked on its page and in a cross-origin frame. The run endpoint returned 200. No completed-run, sign-in, save-recovery or distribution-authorization verification is claimed.'), ('https://pokebonk.com/?lang=en', 'Original PokeBonk project', 'Separate original browser game; the hosted window is not presented as its latest version or as an official partnership.')])}</article>'''
    rendered = ctx['shell'](p+'play/', title, desc, body, script='play.js')
    rendered = rendered.replace('<body>', '<body class="play-page">', 1).replace('</head>', '<link rel="stylesheet" href="/assets/pokebonk/play.css"></head>', 1)
    pages[p+'play/'] = {'title': title, 'desc': desc, 'html': rendered}
    home = pages[p]['html'].replace('<div class="actions">', f'<div class="actions"><a class="button secondary" href="{p}play/">Play in a game window →</a>', 1)
    pages[p]['html'] = home.replace('<div class="guide-index">', f'<div class="guide-index"><a href="{p}play/">Play PokeBonk online<span>Hosted v0.8.27 · expand, minimize and read the guide below</span></a>', 1)
    privacy = pages[p+'privacy/']['html']
    disclosure = '<h2 id="game-window">Third-party game window</h2><p>The Play page loads a game hosted by pokemon-team-builder.org only after you click Play PokeBonk. Your browser then connects to that host and services it uses. The host receives technical request data and controls its game accounts, sessions, storage and progress. Its accounts and saves are separate from pokebonk.com. We do not operate that host or verify its privacy practices. Minimizing keeps the frame connected; close or leave the Play page to end its embedded session. See <a href="https://pokemon-team-builder.org/privacy" target="_blank" rel="noopener noreferrer">Pokemon Team Builder privacy policy ↗ (external, opens in a new tab)</a>.</p>'
    pages[p+'privacy/']['html'] = privacy.replace('<h2>External websites</h2>', disclosure+'<h2>External websites</h2>', 1).replace('Updated October 23, 2026', 'Updated October 26, 2026', 1)
